var t=`0005-kholodnyk`;var r=`world-0005`;var n=`UA`;var o=`eastern-europe`;var a=4;var s=95;var l={en:`Kholodnyk`,ua:`Холодник`};var g={en:`A classic dish from Ukraine, featuring beetroot, potato, kefir, cucumber. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: буряк, картопля, кефір, огірок. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 35 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 35 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:35,i:[[`beetroot`,400,`g`],[`potato`,200,`g`],[`water`,1e3,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[[`kefir`,700,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:4,i:[[`cucumber`,250,`g`],[`green-onion`,70,`g`],[`dill`,20,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,2,`pcs`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:2,i:[[`sour-cream`,90,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:t,id:r,country:`UA`,region:o,servings:4,minutes:95,title:l,text:g,steps:d};export{n as country,u as default,r as id,s as minutes,o as region,a as servings,t as slug,d as steps,g as text,l as title};